package dev.rag.knowledge;
import dev.rag.common.*;
import dev.rag.identity.*;
import jakarta.servlet.http.*;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.multipart.MultipartFile;
import org.springframework.http.*;
import java.nio.file.*;
import java.io.*;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

@RestController @RequestMapping("/api/v1")
public class KnowledgeController {
 private final KnowledgeService service;private final AccessPolicy access;private final PrivateArtifacts files;private final Db db;
 private record Preview(String tenant,String user,long expires,List<Map<String,Object>> files){}
 private final Map<String,Preview> previews=new ConcurrentHashMap<>();
 public KnowledgeController(KnowledgeService service,AccessPolicy access,PrivateArtifacts files,Db db){this.service=service;this.access=access;this.files=files;this.db=db;}
 @GetMapping("/documents") public Object list(HttpServletRequest r,@RequestParam(required=false)String kbId){return service.list(access.actor(r),kbId,false,null);}
 @GetMapping("/admin/documents") public Object adminList(HttpServletRequest r,@RequestParam(required=false)String kbId,@RequestParam(defaultValue="LIVE")String status){return service.list(access.actor(r),kbId,true,status);}
 @GetMapping("/documents/{id}") public Object get(HttpServletRequest r,@PathVariable String id){return service.get(access.actor(r),id);}
 @PostMapping(value="/admin/documents",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) @ResponseStatus(HttpStatus.ACCEPTED) public Object upload(HttpServletRequest r,@RequestParam("file")MultipartFile file,@RequestParam String kbId,@RequestParam(defaultValue="{}")String buildConfig,@RequestHeader("Idempotency-Key")String key)throws IOException{return service.upload(access.actor(r),kbId,null,name(file),file.getBytes(),key,Json.object(buildConfig));}
 @PostMapping(value="/admin/documents/batch",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) public Object batch(HttpServletRequest r,@RequestParam("files")List<MultipartFile> input,@RequestParam String kbId,@RequestHeader("Idempotency-Key")String key)throws IOException{Actor a=access.actor(r);access.requireAdmin(a);if(input.size()>100)throw new ApiException(413,"INPUT_TOO_LARGE","最多100个文件");List<Object> results=new ArrayList<>();int i=0;for(var f:input){try{results.add(service.upload(a,kbId,null,name(f),f.getBytes(),key+"-"+i++,Map.of()));}catch(ApiException e){results.add(Map.of("fileName",name(f),"status","FAILED","errorCode",e.code));}}return results;}
 @PostMapping(value="/admin/documents/{id}/versions",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) @ResponseStatus(HttpStatus.ACCEPTED) public Object version(HttpServletRequest r,@PathVariable String id,@RequestParam("file")MultipartFile file,@RequestParam(defaultValue="{}")String buildConfig,@RequestHeader("Idempotency-Key")String key)throws IOException{Actor a=access.actor(r);var d=service.get(a,id);return service.upload(a,d.get("kbId").toString(),id,name(file),file.getBytes(),key,Json.object(buildConfig));}
 @GetMapping("/documents/{id}/versions/{versionId}/preview") public Object preview(HttpServletRequest r,@PathVariable String id,@PathVariable String versionId){return service.preview(access.actor(r),id,versionId);}
 @GetMapping("/documents/{id}/artifacts/{artifactId}") public void artifact(HttpServletRequest r,HttpServletResponse response,@PathVariable String id,@PathVariable String artifactId){Actor a=access.actor(r);access.guard(a,List.of(id),()->{var artifact=db.one("SELECT storage_key,kind FROM artifact WHERE tenant_id=:t AND document_id=:d AND id=:id AND status='READY'",Db.params("t",a.tenantId(),"d",id,"id",artifactId));response.setHeader("Content-Disposition","attachment; filename=\"source.bin\"");response.setHeader("X-Content-Type-Options","nosniff");response.setHeader("Cache-Control","no-store");response.setContentType("application/octet-stream");try{response.getOutputStream().write(files.read(artifact.get("storage_key").toString()));response.flushBuffer();}catch(IOException e){throw new ApiException(503,"DOWNLOAD_INTERRUPTED","下载中断");}return null;});}
 @PostMapping("/admin/documents/{id}/{action:trash|restore|purge}") public Object lifecycle(HttpServletRequest r,@PathVariable String id,@PathVariable String action,@RequestBody Map<String,Object>b){return service.lifecycle(access.actor(r),id,action,IdentityService.number(b,"expectedVersion"));}
 @GetMapping("/admin/jobs") public Object jobs(HttpServletRequest r){return service.jobs(access.actor(r),null);}
 @GetMapping("/admin/jobs/{id}") public Object job(HttpServletRequest r,@PathVariable String id){var list=(List<?>)service.jobs(access.actor(r),id);if(list.isEmpty())throw ApiException.missing();return list.getFirst();}
 @PostMapping("/admin/jobs/{id}/{action:retry|cancel}") public Object control(HttpServletRequest r,@PathVariable String id,@PathVariable String action){return service.controlJob(access.actor(r),id,action.equals("cancel"));}
 @PostMapping("/admin/builds/{id}/accept-warnings") public Object accept(HttpServletRequest r,@PathVariable String id,@RequestBody Map<String,Object>b){return service.accept(access.actor(r),id,b);}
 @PostMapping("/admin/import-previews") public Object importPreview(HttpServletRequest r,@RequestBody Map<String,Object>b){Actor a=access.actor(r);access.requireAdmin(a);String alias=Json.str(b,"rootAlias");if(!alias.isBlank()&&!alias.equals("default"))throw IdentityService.invalid("rootAlias 无效");var listing=files.preview(Json.str(b,"relativePath"));previews.entrySet().removeIf(e->e.getValue().expires()<System.currentTimeMillis());if(previews.size()>=100)throw new ApiException(429,"RATE_LIMITED","导入预览过多");String id=Json.id();previews.put(id,new Preview(a.tenantId(),a.userId(),System.currentTimeMillis()+600000,listing));return Map.of("estimateId",id,"files",listing,"estimatedModelCost",0,"mode","BM25_ONLY");}
 @PostMapping("/admin/imports") public Object imports(HttpServletRequest r,@RequestBody Map<String,Object>b){Actor a=access.actor(r);access.requireAdmin(a);String id=Json.str(b,"estimateId");var p=previews.get(id);if(p==null||p.expires()<System.currentTimeMillis()||!p.tenant().equals(a.tenantId())||!p.user().equals(a.userId()))throw new ApiException(409,"ESTIMATE_EXPIRED","导入预览已失效");Object input=b.get("files");if(!(input instanceof List<?> selected)||selected.isEmpty()||selected.size()>100)throw IdentityService.invalid("files 无效");List<Object> results=new ArrayList<>();for(Object f:selected){String path=f.toString();var entry=p.files().stream().filter(e->e.get("relativePath").equals(path)).findFirst().orElseThrow(()->IdentityService.invalid("文件不在预览内"));try{Path actual=files.importPath(path);byte[] bytes=Files.readAllBytes(actual);if(!entry.get("sha256").equals(HexFormat.of().formatHex(AccessPolicy.hash(bytes))))throw new ApiException(409,"SOURCE_CHANGED","导入文件已变化");results.add(service.upload(a,IdentityService.required(b,"kbId",36),null,actual.getFileName().toString(),bytes,id+"-"+results.size(),Map.of()));}catch(IOException e){throw new ApiException(503,"IMPORT_UNAVAILABLE","导入文件不可读");}}return results;}
 private String name(MultipartFile f){String name=f.getOriginalFilename();if(name==null||name.isBlank()||name.length()>512)throw IdentityService.invalid("文件名无效");return name.replace('\\','/').substring(name.replace('\\','/').lastIndexOf('/')+1);}
 @PostMapping(value="/admin/wiki-imports",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) public Object wiki(HttpServletRequest r,@RequestParam("file")MultipartFile file,@RequestParam String kbId,@RequestParam(defaultValue="{}")String buildConfig,@RequestHeader("Idempotency-Key")String key)throws IOException{Actor a=access.actor(r);access.requireAdmin(a);if(file.getSize()>25*1024*1024)throw new ApiException(413,"INPUT_TOO_LARGE","Wiki包最多25MiB");List<Object> results=new ArrayList<>();for(var page:WikiPackage.split(file.getBytes()))results.add(service.upload(a,kbId,null,page.name(),page.bytes(),key+"-"+results.size(),Json.object(buildConfig)));return results;}
}
